// API Service Layer for Yobuildplus
// Centralizes all fetch calls to the backend
const API_BASE_URL = ("TURBOPACK compile-time value", "http://localhost:3001") || 'http://localhost:3001';
// Generic fetch wrapper with error handling
async function apiFetch(endpoint, options) {
    const url = `${API_BASE_URL}${endpoint}`;
    const response = await fetch(url, {
        headers: {
            'Content-Type': 'application/json',
            ...options?.headers
        },
        ...options
    });
    if (!response.ok) {
        const error = await response.json().catch(()=>({
                message: 'Network error'
            }));
        throw new Error(error.message || `HTTP error ${response.status}`);
    }
    return response.json();
}
const buildersApi = {
    // Get all builders with optional filters
    getAll: (filters)=>{
        const params = new URLSearchParams();
        if (filters?.province) params.append('province', filters.province);
        if (filters?.category) params.append('category', filters.category);
        if (filters?.minRating) params.append('minRating', String(filters.minRating));
        if (filters?.search) params.append('search', filters.search);
        const query = params.toString() ? `?${params.toString()}` : '';
        return apiFetch(`/api/builders${query}`);
    },
    // Get single builder by slug
    getBySlug: (slug)=>{
        return apiFetch(`/api/builders/${slug}`);
    },
    // Update builder profile
    updateProfile: (id, data)=>{
        return apiFetch(`/api/builders/${id}`, {
            method: 'PATCH',
            body: JSON.stringify(data)
        });
    }
};
const adminApi = {
    // Get pending approvals
    getPendingBuilders: ()=>{
        return apiFetch('/api/admin/builders/pending');
    },
    // Approve a builder
    approveBuilder: (id)=>{
        return apiFetch(`/api/admin/builders/${id}/approve`, {
            method: 'POST'
        });
    },
    // Reject a builder
    rejectBuilder: (id, reason)=>{
        return apiFetch(`/api/admin/builders/${id}/reject`, {
            method: 'POST',
            body: JSON.stringify({
                reason
            })
        });
    },
    // Get dashboard stats
    getStats: ()=>{
        return apiFetch('/api/admin/stats');
    }
};
const categoriesApi = {
    // Get all categories with subcategories
    getAll: ()=>{
        return apiFetch('/api/categories');
    },
    // Get single category by slug
    getBySlug: (slug)=>{
        return apiFetch(`/api/categories/${slug}`);
    }
};
const authApi = {
    // Login with email/password
    login: (credentials)=>{
        return apiFetch('/api/auth/login', {
            method: 'POST',
            body: JSON.stringify(credentials)
        });
    },
    // Register new user
    register: (data)=>{
        return apiFetch('/api/auth/register', {
            method: 'POST',
            body: JSON.stringify(data)
        });
    },
    // Get current user
    me: (token)=>{
        return apiFetch('/api/auth/me', {
            headers: {
                Authorization: `Bearer ${token}`
            }
        });
    }
};
const __TURBOPACK__default__export__ = {
    builders: buildersApi,
    admin: adminApi,
    categories: categoriesApi,
    auth: authApi
};
